import 'server-only';
import {cache} from 'react';
import {apiGet,getPage,getSite,record,list,str,optional,media,ApiError} from './api';
import {homeContent,type HomeContent} from './home-content';
import {publicCopy,type ApplicationDTO} from './public-content';
import {parseCatalogueQuery} from './catalogue';
import type {Locale} from './locales';
export const getShell=cache(async(locale:Locale)=>{const [shared,site]=await Promise.all([getPage(locale,'shared'),getSite(locale)]);const base=structuredClone(homeContent[locale]);const nav=shared.sections.find(s=>s.key==='navigation');const footer=shared.sections.find(s=>s.key==='footer');if(nav){const lines=nav.body.split('\n');base.nav=base.nav.map((label,i)=>lines[i]?.trim()||label);}base.footer.tagline=footer?.body.split('\n')[0]||'';base.footer.note=footer?.body.split('\n').slice(1).join('\n')||'';return {...base,banners:{hero:shared.sections.find(s=>s.key==='catalogue-hero')?.image||'',cta:shared.sections.find(s=>s.key==='catalogue-cta')?.image||''},brand:site.brand,logo:site.logo,socials:[{label:'Instagram',url:site.contacts.instagram},{label:'LinkedIn',url:site.contacts.linkedin}].filter(s=>/^https:\/\//.test(s.url))};});
export const getHome=cache(async(locale:Locale)=>{const [page,shell]=await Promise.all([getPage(locale,'home'),getShell(locale)]);const c:HomeContent=structuredClone(shell);const groups=['hero','collection','quarry','introduction','featured','craft','applications','quality','contact'] as const;for(const key of groups){const section=page.sections.find(s=>s.key===key);const group=c[key] as unknown as Record<string,unknown>;group.title=section?.title||'';group.description=section?.body||'';if('action'in group)group.action=section?.cta||'';}
 c.explore=page.sections.find(s=>s.key==='hero')?.cta||c.explore;
 c.qualities=page.sections.filter(s=>s.key.startsWith('quality-item-')).map(s=>({title:s.title,description:s.body}));c.craft.steps=page.sections.filter(s=>s.key.startsWith('craft-step-')).map(s=>s.title);c.quality.points=page.sections.filter(s=>s.key.startsWith('quality-point-')).map(s=>s.title);c.meta={title:optional(page.seo.title)||page.title,description:optional(page.seo.description)||page.description};return {content:c,page};});
export const getPublicContent=cache(async(locale:Locale,key:string)=>{const page=await getPage(locale,key);const c=structuredClone(publicCopy[locale]);const hero=page.sections.find(s=>s.key==='hero');const cta=page.sections.find(s=>s.key==='cta');if(key==='about'){c.aboutTitle=hero?.title||page.title;c.aboutIntro=hero?.body||page.description;const story=page.sections.find(s=>s.key==='story');c.companyTitle=story?.title||'';c.companyText=story?.body||'';c.companyDraft='';c.qualityTitles=page.sections.filter(s=>s.key.startsWith('value-')).map(s=>s.title);c.qualityTexts=page.sections.filter(s=>s.key.startsWith('value-')).map(s=>s.body);const process=page.sections.find(s=>s.key==='process');c.processTitle=process?.title||'';c.processIntro=process?.body||'';c.qualityNote=page.sections.find(s=>s.key==='quality')?.body||'';}
 if(key==='applications'){c.applicationsTitle=hero?.title||page.title;c.applicationsIntro=hero?.body||page.description;const gallery=page.sections.find(s=>s.key==='gallery');c.galleryTitle=gallery?.title||'';c.galleryIntro=gallery?.body||'';c.bandTitle=cta?.title||'';c.bandAction=cta?.cta||c.bandAction;c.bandItems=[];}
 if(key==='contact'){c.contactPageTitle=hero?.title||page.title;c.contactPageIntro=hero?.body||page.description;const enquiry=page.sections.find(s=>s.key==='enquiry');c.enquiry=enquiry?.title||'';c.enquiryText=enquiry?.body||'';}
 c.contactTitle=cta?.title||'';c.contactIntro=cta?.body||'';c.contactAction=cta?.cta||'';return {c,page,heroImage:hero?.image||''};});
function application(v:unknown):ApplicationDTO{const a=record(v);return {slug:str(a.slug),title:str(a.title),description:optional(a.description),image:media(a.image),gallery:list(a.gallery).map(media),considerations:[],temporary:a.temporary===true,stone_types:[],catalogue:parseCatalogueQuery({application:str(a.slug)})};}
export const getApplications=cache(async(locale:Locale)=>list(record(await apiGet(`applications?locale=${locale}&per_page=48`)).data).map(application));
export const getApplication=cache(async(locale:Locale,slug:string)=>{if(!/^[a-z0-9-]{1,100}$/.test(slug))return null;try{return application(record(await apiGet(`applications/${slug}?locale=${locale}`)).data);}catch(e){if(e instanceof ApiError&&e.status===404)return null;throw e;}});
export const getAboutContent=cache(async(locale:Locale)=>{const {c,page,heroImage}=await getPublicContent(locale,'about');const material=page.sections.find(s=>s.key==='material');return {...c,heroImage,storyImage:page.sections.find(s=>s.key==='story')?.image||'',material:{title:material?.title||'',text:material?.body||'',image:material?.image||''},stages:page.sections.filter(s=>s.key.startsWith('stage-')).map(s=>({id:s.key,title:s.title,text:s.body,image:s.image}))};});
export async function getContactDetails(locale:Locale){return (await getSite(locale)).contacts;}
